import{state}from"./state.js";import{renderAll}from"./ui.js";import{showToast,showMobileEventNotification}from"./utils.js";import{scheduleSave,addHistoryEntry,updateBalanceLocally}from"./action-helpers.js";function getAwardDescription(t){const r=prompt("Описание:",t>0?"Бонус от родителей":"Списано родителями");return r?.trim()||(t>0?"Начисление":"Списание")}export function adminAwardCoins(){if(!state.isAdmin||!state.currentChildId)return showToast("Сначала выберите ребенка","error");const t=prompt("Количество монет (можно отрицательное):");if(null===t)return;const r=parseInt(t);if(!r)return showToast("Некорректная сумма","error");const e=getAwardDescription(r);e&&(updateBalanceLocally(state.currentChildId,r),addHistoryEntry({type:r>0?"earn":"spend",amount:Math.abs(r),description:e,childIdOverride:state.currentChildId}),scheduleSave(),renderAll(),showMobileEventNotification(`${r>0?"Начислено":"Списано"}: ${Math.abs(r)} мон.`,"success","Balance updated"))}